	 if(d.collection){S.collection=d.collection;if(d.collection==='shots')Clips.browse();else renderCollection();return}
	 if(d.sceneNoteEdit!==undefined)return beginSceneNoteEdit(d.sceneNoteEdit,d.owner)
	 if(d.sceneNoteCancel!==undefined)return cancelSceneNoteEdit()
