 if(d.detail)return await openDetail(d.detail,d.owner);
 if(d.sceneMenu)return openSceneMenu(d.sceneMenu,d.owner);
 if(d.subtitle!==undefined)return Clips.locate(S.p.transcript.segments[Number(d.subtitle)].start);
 if(d.annotation){const note=S.p.annotations.find(a=>a.id===d.annotation);if(note)Clips.locate(note.time);return openNote(d.annotation);}if(d.legacyNote){const shot=S.p.shots.find(a=>a.id===d.legacyNote);if(shot)Clips.locate(shot.start);return openNote(null,d.legacyNote);}
 if(d.frameMode){S.frameMode=d.frameMode;S.frameTags=[];renderBoard();if(d.frameMode==='scenes'&&S.p&&!S.p.analysis&&S.p.shots.length<=1)await begin('scenes');return}
 if(d.frameTag){S.frameTags=S.frameTags.includes(d.frameTag)?S.frameTags.filter(t=>t!==d.frameTag):[...S.frameTags,d.frameTag];return paintBoard()}
 if(d.musicTag){S.musicTags=S.musicTags.includes(d.musicTag)?S.musicTags.filter(t=>t!==d.musicTag):[...S.musicTags,d.musicTag];return paintMusic()}
 if(d.removeTag){S.modal.tags=S.modal.tags.filter(t=>t!==d.removeTag);return renderTagModal()}
 if(d.addTag){if(!S.modal.tags.includes(d.addTag))S.modal.tags.push(d.addTag);return renderTagModal()}
 if(d.musicSource){const a=findAsset('music',d.musicSource,d.owner);if(a)await goSource(d.owner,a.time);return}
 if(d.localPlay)return playAudio(S.music.find(a=>a.id===d.localPlay));
 if(d.assetOpen){const a=findAsset(d.kind,d.assetOpen,d.owner);if(a){if(d.kind==='audio_clips')playAudio(a);else download(a.url,a.title)}return}
 if(d.retryUpload!==undefined){S.uploads[Number(d.retryUpload)].status='queued';return enqueueRetry()}
 if(d.uploadOpen)return selectProject(d.uploadOpen);
	 if(d.action)await runAction(d.action,el);
