async function enqueueRetry(){if(S.uploading)return;const pending=S.uploads.filter(r=>r.status==='queued');if(!pending.length)return;S.uploads=S.uploads.filter(r=>r.status!=='queued');await enqueue(pending.map(r=>r.file),pending[0].music)}
