window.addEventListener('pagehide',()=>{const v=$('#video');if(v&&!S.mediaLoading&&S.p)writeSetting('position:'+S.p.id,v.currentTime)});
window.addEventListener('beforeunload',e=>{if(S.uploading){e.preventDefault();e.returnValue=''}});
async function bootstrap(){const params=new URLSearchParams(location.search);const route=AssetLibrary.resolveAssetRoute(params.get('view'),params.get('tab'));S.view=route.view;if(route.tab)S.assetTab=route.tab;shell();try{const [projects,music]=await Promise.all([api('/api/projects'),api('/api/music')]);S.projects=projects.projects;S.music=music.tracks;S.loading=false;const preferred=params.get('project')||readSetting('last-project',null)||localStorage.getItem('broll-last-project');const p=S.projects.find(p=>p.id===preferred)||S.projects[0];if(p)await selectProject(p.id,{autoplay:false,stayView:true});else{writeRoute();shell();}pollTimer=setTimeout(poll,1500)}catch(error){S.loading=false;$('#content').innerHTML=`<div class="empty large"><h2>本机服务暂未连接</h2><p>${esc(error.message)}</p>${button('重试','reload')}</div>`;toast(error.message)}}
let layoutFrame;window.addEventListener('resize',()=>{cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>{S.forceFollow=true;paintClock()})});
bootstrap();
